async def on_startup(app: web.Application):
    app["warmup_task"] = asyncio.create_task(get_dashboard_data(force=True))
    app["bot_task"] = asyncio.create_task(realtime_bot_loop())


async def on_cleanup(app: web.Application):
    for key in ("warmup_task", "bot_task"):
        task = app.get(key)
        if task and not task.done():
            task.cancel()


def create_app() -> web.Application:
    app = web.Application()
    app.on_startup.append(on_startup)
    app.on_cleanup.append(on_cleanup)

    app.router.add_get("/", handle_web_index)
    app.router.add_get("/api/health", handle_health)
    app.router.add_get("/api/overview", handle_overview)
    app.router.add_get("/download/pc-bundle", handle_download_zip)
    app.router.add_get("/static/{filename}", handle_web_static)

    app.router.add_get("/sentinel", handle_sentinel_redirect)
    app.router.add_get("/sentinel/", handle_sentinel_index)
    app.router.add_get("/sentinel/manifest.json", handle_sentinel_manifest)
    app.router.add_get("/sentinel/icon.svg", handle_sentinel_icon)
    app.router.add_get("/sentinel/api/health", handle_health)
    app.router.add_get("/sentinel/api/dashboard", handle_sentinel_dashboard)
    app.router.add_get("/sentinel/api/search", handle_sentinel_search)
    app.router.add_get("/sentinel/api/article", handle_sentinel_article)
    app.router.add_post("/sentinel/api/ai-analyze", handle_sentinel_ai)
    app.router.add_get("/sentinel/api/bot/status", handle_bot_status)
    app.router.add_post("/sentinel/api/bot/config", handle_bot_config)
    app.router.add_post("/sentinel/api/bot/run", handle_bot_run)
    app.router.add_post("/sentinel/api/bot/kill", handle_bot_kill)
    app.router.add_post("/sentinel/api/bot/close", handle_bot_close)
    app.router.add_get("/sentinel/api/bot/bridge/poll", handle_bridge_poll)
    app.router.add_post("/sentinel/api/bot/mt5-report", handle_mt5_report)
    app.router.add_get("/sentinel/api/bot/download/ea", handle_download_ea)
    app.router.add_get("/sentinel/api/bot/download/worker", handle_download_worker)
    app.router.add_get("/sentinel/static/{filename}", handle_sentinel_static)

    return app


if __name__ == "__main__":
    port = _safe_int("PORT", 8080)
    web.run_app(create_app(), host="0.0.0.0", port=port)
